import sys
sys.setrecursionlimit(200000)
lines = sys.stdin.read().splitlines()
if lines:
    parts = lines[0].split()
    n, m = int(parts[0]), int(parts[1])
    adj = [[] for _ in range(n)]
    for line in lines[1:1+m]:
        uv = [int(x) for x in line.split()]
        if len(uv) == 2:
            adj[uv[0]].append(uv[1]); adj[uv[1]].append(uv[0])
    disc = [-1] * n
    low = [-1] * n
    timer = 0
    bridges = 0
    def dfs(u, p):
        nonlocal timer, bridges
        disc[u] = low[u] = timer
        timer += 1
        for v in adj[u]:
            if v == p: continue
            if disc[v] != -1: low[u] = min(low[u], disc[v])
            else:
                dfs(v, u)
                low[u] = min(low[u], low[v])
                if low[v] > disc[u]: bridges += 1
    for i in range(n):
        if disc[i] == -1: dfs(i, -1)
    print(bridges)
